import {Routes,Route,Navigate,Link,NavLink,useNavigate,useLocation,useSearchParams} from 'react-router-dom';
import {useQuery,useQueryClient} from '@tanstack/react-query';
import {motion,AnimatePresence} from 'framer-motion';
import {ShieldCheck,Shield,LayoutDashboard,AtSign,LockKeyhole,Bell,Settings,LogOut,ArrowRight,ArrowUpRight,Plus,Search,RefreshCw,Trash2,Eye,EyeOff,Copy,Check,ChevronRight,Menu,X,KeyRound,AlertTriangle,CheckCircle2,Clock,Activity,ScanSearch,Fingerprint,Sparkles,MonitorSmartphone,UserRound,LoaderCircle,Heart,ChevronDown,FileClock,ShieldAlert,Info,Lock,Archive} from 'lucide-react';
