type IconType=typeof ShieldCheck;

const getError=(e:unknown)=>e instanceof Error?e.message:'Ocorreu um erro inesperado';
const statusLabel:Record<string,string>={pending:'Aguardando',queued:'Na fila',exposed:'Exposto',clear:'Nenhuma exposição conhecida',unavailable:'Indisponível'};
const statusType=(s:string)=>s==='exposed'?'danger':s==='clear'?'success':'warning';
function IconLogo({large=false}:{large?:boolean}){return <div className={`brand ${large?'large':''}`}><span className="brand-mark"><img src="/favicon.svg" alt="" width={large?32:27} height={large?32:27}/></span><span>Co<span className="brand-accent">Free</span><small className="brand-dot">.</small></span></div>}
function Button({children,onClick,type='button',kind='primary',disabled=false,loading=false,className=''}:{children:ReactNode;onClick?:()=>void;type?:'submit'|'button';kind?:'primary'|'ghost'|'soft'|'danger';disabled?:boolean;loading?:boolean;className?:string}){return <button type={type} className={`btn btn-${kind} ${className}`} onClick={onClick} disabled={disabled||loading}>{loading?<LoaderCircle size={16} className="spin"/>:null}{children}</button>}
function Tag({status}:{status:string}){return <span className={`tag tag-${statusType(status)}`}><span className="tag-dot"/>{statusLabel[status]||status}</span>}
function Empty({icon:Icon=Archive,title,description,action}:{icon?:IconType;title:string;description:string;action?:ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={24}/></span><h3>{title}</h3><p>{description}</p>{action}</div>}
function Heading({eyebrow,title,description,action}:{eyebrow?:string;title:string;description?:string;action?:ReactNode}){return <div className="page-head"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{description&&<p>{description}</p>}</div>{action&&<div className="heading-action">{action}</div>}</div>}
function Field({label,value,onChange,type='text',placeholder='',required=false,autoComplete,children}:{label:string;value:string;onChange:(v:string)=>void;type?:string;placeholder?:string;required?:boolean;autoComplete?:string;children?:ReactNode}){return <label className="field"><span>{label}</span><div className="field-wrap"><input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} required={required} autoComplete={autoComplete}/>{children}</div></label>}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){useEffect(()=>{const f=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',f);return()=>window.removeEventListener('keydown',f)},[onClose]);return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><motion.div role="dialog" aria-modal="true" aria-label={title} initial={{opacity:0,scale:.96,y:10}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:.96,y:10}} transition={{duration:.18}} className="modal"><div className="modal-head"><h2>{title}</h2><button className="icon-btn" aria-label="Fechar" onClick={onClose}><X size={20}/></button></div>{children}</motion.div></div>}
function Alert({message,kind='error'}:{message:string;kind?:'error'|'success'|'info'}){return <div role="status" className={`alert alert-${kind}`}>{kind==='error'?<AlertTriangle size={17}/>:<CheckCircle2 size={17}/>}<span>{message}</span></div>}
function PasswordRules({password,confirm}:{password:string;confirm:string}){
 const rules = [{ok:password.length>=12,label:'No mínimo 12 caracteres'},
   {ok:password.length>=16,label:'16 ou mais caracteres (recomendado)'},
   {ok:!!password && !!confirm && password===confirm,label:'As senhas coincidem'}];
 return <div className="password-rules" aria-live="polite">
   {password.length>0&&password.length<12&&<p className="password-warning">A senha deve conter pelo menos 12 caracteres.</p>}
   {rules.map(rule=><span key={rule.label} className={rule.ok?'rule-ok':'rule-pending'}>
     {rule.ok?<CheckCircle2 size={14}/>:<span className="rule-ring"/>}{rule.label}
   </span>)}
 </div>
}
function FeatureCard({icon:Icon,title,description}:{icon:IconType;title:string;description:string}){return <div className="feature"><div className="feature-icon"><Icon size={23}/></div><h3>{title}</h3><p>{description}</p></div>}

function Landing(){const{user}=useAuth();return <div className="landing"><header className="land-header wrap"><Link to="/" aria-label="CoFree início"><IconLogo/></Link><nav><a href="#recursos">Recursos</a><a href="#seguranca">Segurança</a><Link to={user?'/app':'/entrar'}>Minha conta</Link></nav><Link className="btn btn-primary" to={user?'/app':'/cadastro'}>{user?'Abrir painel':'Começar agora'} <ArrowRight size={17}/></Link></header><div className="hero-wrap"><main className="hero wrap"><div className="hero-copy"><span className="hero-chip"><span/> SUA VIDA DIGITAL, PROTEGIDA</span><h1>Seu mundo digital.<br/><em>Mais seguro.</em><br/>Mais seu.</h1><p>Descubra vazamentos, acompanhe suas contas e guarde suas credenciais em um cofre criptografado. Tudo em um lugar, sem complicação.</p><div className="hero-actions"><Link to={user?'/app':'/cadastro'} className="btn btn-primary btn-big">Proteja minhas contas <ArrowUpRight size={19}/></Link><a href="#recursos" className="btn btn-outline btn-big">Conheça o CoFree <ChevronRight size={18}/></a></div><div className="hero-trust flex items-center gap-2"><ShieldCheck size={19}/> Criptografia no seu dispositivo <span>•</span> Privacidade por padrão</div></div><div className="hero-art"><div className="orb orb-one"/><div className="orb orb-two"/><motion.div className="hero-preview" initial={{y:28,opacity:0}} animate={{y:0,opacity:1}} transition={{delay:.15,duration:.65}}><div className="preview-top"><div className="preview-dots"><i/><i/><i/></div><span>VISÃO DE SEGURANÇA</span><ShieldCheck size={18}/></div><div className="preview-content"><span className="preview-caption">Seus dados, sob seu controle</span><div className="preview-medal"><span><ShieldCheck size={42}/></span></div><h3>Proteção inteligente</h3><p>Monitore exposições e aja antes que um risco se torne um problema.</p><div className="preview-rows"><div><span className="fake-avatar"><AtSign size={18}/></span><span>Monitoramento contínuo<small>Seus e-mails acompanhados</small></span><CheckCircle2 size={18}/></div><div><span className="fake-avatar purple"><LockKeyhole size={18}/></span><span>Vault criptografado<small>Seus segredos só com você</small></span><CheckCircle2 size={18}/></div></div></div></motion.div><span className="float-tag"><span className="float-bullet"/> Privacidade em primeiro lugar</span></div></main></div><section id="recursos" className="features-section wrap"><div className="center-title"><span className="eyebrow">PROTEÇÃO DE VERDADE</span><h2>Tudo o que você precisa.<br/>Nada do que você não precisa.</h2><p>Ferramentas de segurança pensadas para facilitar a sua rotina.</p></div><div className="features-grid"><FeatureCard icon={AtSign} title="Monitoramento de vazamentos" description="Acompanhe seus e-mails e descubra exposições reportadas em bases conhecidas."/><FeatureCard icon={LockKeyhole} title="Cofre privado" description="Guarde suas credenciais com criptografia no navegador e chaves que só você controla."/><FeatureCard icon={ScanSearch} title="Verificação de senhas" description="Confira senhas expostas com consultas privadas à base Pwned Passwords."/><FeatureCard icon={Bell} title="Alertas relevantes" description="Saiba quando novas exposições forem identificadas e receba orientações claras."/></div></section><section id="seguranca" className="security-strip"><div className="wrap security-content"><div className="security-orbit"><Shield size={90}/></div><div><span className="eyebrow">PRIVACIDADE NÃO É OPCIONAL</span><h2>Suas senhas são suas.<br/>Só suas.</h2><p>O Vault cifra suas credenciais antes de enviá-las ao servidor. Nem mesmo a equipe do CoFree pode ler o conteúdo armazenado.</p><Link to="/cadastro" className="btn btn-primary">Criar minha conta <ArrowRight size={17}/></Link></div></div></section><footer className="site-footer wrap"><IconLogo/><p>© 2026 CoFree. Desenvolvido pela Vela.</p><span>Sua segurança importa.</span></footer></div>}

function AuthPage({mode}:{mode:'login'|'register'|'forgot'|'reset'|'verify'}){
 const navigate=useNavigate(),{refresh}=useAuth(),[params]=useSearchParams();
 const[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');
 const descriptions={login:['Bem-vindo de volta','Entre para continuar protegendo seu mundo digital.'],register:['Comece com segurança','Sua proteção digital começa por aqui.'],forgot:['Recupere seu acesso','Enviaremos um link de redefinição ao seu e-mail.'],reset:['Crie uma nova senha','Escolha uma senha forte para sua conta.'],verify:['Confirme seu e-mail','Estamos verificando seu endereço de e-mail.']};
 useEffect(()=>{if(mode==='verify'&&params.get('token')){void api('/auth/verify',{method:'POST',body:JSON.stringify({token:params.get('token')})}).then(()=>setMessage('E-mail confirmado! Agora você pode entrar.')).catch(e=>setError(getError(e)));}},[mode,params]);
 const submit=async(e:FormEvent)=>{e.preventDefault();setError('');setMessage('');setBusy(true);try{if(mode==='login'){await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})});await refresh();navigate('/app');return;}if(mode==='register'){if(password.length<12)throw Error('A senha deve conter pelo menos 12 caracteres.');if(password!==confirm)throw Error('As senhas não coincidem');const response=await api<{message:string;email_delivered:boolean}>('/auth/register',{method:'POST',body:JSON.stringify({name,email,password})});setMessage(response.message+(response.email_delivered?'':' O envio por e-mail não foi confirmado; contate o administrador.'));return;}if(mode==='forgot'){const r=await api<{message:string}>('/auth/password/forgot',{method:'POST',body:JSON.stringify({email})});setMessage(r.message);return;}if(mode==='reset'){if(password.length<12)throw Error('A senha deve conter pelo menos 12 caracteres.');if(password!==confirm)throw Error('As senhas não coincidem');const r=await api<{message:string}>('/auth/password/reset',{method:'POST',body:JSON.stringify({token:params.get('token'),password})});setMessage(r.message);return;}}catch(e){setError(getError(e))}finally{setBusy(false)}};
 const title=descriptions[mode][0],desc=descriptions[mode][1];
 return <div className="auth-layout"><div className="auth-side"><Link to="/"><IconLogo large/></Link><div className="auth-side-body"><div className="auth-big-shield"><ShieldCheck size={102} strokeWidth={1.3}/></div><h2>Mais tranquilidade.<br/><span>Mais controle.</span></h2><p>Um jeito mais inteligente de cuidar da sua vida online.</p></div><small>© 2026 CoFree · Uma solução Vela</small></div><main className="auth-main"><div className="auth-mobile-logo"><Link to="/"><IconLogo/></Link></div><div className="auth-box"><span className="auth-asterisk"><Sparkles size={20}/></span><h1>{title}</h1><p className="muted">{desc}</p>{error&&<Alert message={error}/>} {message&&<Alert kind="success" message={message}/>}<form onSubmit={submit} className="auth-form">{mode==='register'&&<Field label="Seu nome" value={name} onChange={setName} placeholder="Como podemos chamar você?" required/>}{['login','register','forgot'].includes(mode)&&<Field label="E-mail" value={email} onChange={setEmail} type="email" placeholder="voce@exemplo.com" autoComplete="email" required/>}{['login','register','reset'].includes(mode)&&<Field label={mode==='reset'?'Nova senha':'Senha'} value={password} onChange={setPassword} type="password" placeholder="Pelo menos 12 caracteres" autoComplete={mode==='login'?'current-password':'new-password'} required/>}{['register','reset'].includes(mode)&&<PasswordRules password={password} confirm={confirm}/>}{['register','reset'].includes(mode)&&<Field label="Confirmar senha" type="password" value={confirm} onChange={setConfirm} placeholder="Digite sua senha novamente" required/>}{mode==='login'&&<div className="forgot-link"><Link to="/esqueci-senha">Esqueceu sua senha?</Link></div>}{mode!=='verify'&&<Button type="submit" className="full" loading={busy}>{mode==='login'?'Entrar na minha conta':mode==='register'?'Criar conta gratuita':mode==='forgot'?'Enviar instruções':'Salvar nova senha'} <ArrowRight size={17}/></Button>}</form><div className="auth-switch">{mode==='login'?<>Ainda não tem conta? <Link to="/cadastro">Cadastre-se</Link></>:mode==='register'?<>Já tem uma conta? <Link to="/entrar">Entrar</Link></>:<Link to="/entrar">Voltar para o login</Link>}</div><div className="auth-privacy"><Lock size={14}/> Seus dados protegidos por criptografia e boas práticas de segurança</div></div></main></div>;
}

const navigation:[string,string,IconType][]=[['/app','Visão geral',LayoutDashboard],['/app/emails','Meus e-mails',AtSign],['/app/vault','Meu Vault',LockKeyhole],['/app/gerador','Gerador de senhas',KeyRound],['/app/senhas','Verificar senhas',ScanSearch],['/app/notificacoes','Notificações',Bell],['/app/sessoes','Sessões ativas',MonitorSmartphone],['/app/configuracoes','Configurações',Settings]];
function AppShell({children}:{children:ReactNode}){const{user,logout}=useAuth(),[mobile,setMobile]=useState(false),navigate=useNavigate(),location=useLocation();useEffect(()=>setMobile(false),[location.pathname]);return <div className="shell"><AnimatePresence>{mobile&&<motion.div className="mobile-shade" onClick={()=>setMobile(false)} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/>}</AnimatePresence><aside className={`sidebar ${mobile?'sidebar-open':''}`}><div className="sidebar-logo"><Link to="/app"><IconLogo/></Link><button onClick={()=>setMobile(false)} className="icon-btn mobile-close"><X size={20}/></button></div><div className="workspace-label">WORKSPACE <ChevronDown size={13}/></div><div className="workspace-card"><span className="workspace-avatar"><Shield size={20}/></span><span><strong>Meu espaço</strong><small>Plano pessoal</small></span><ChevronDown size={15}/></div><div className="nav-heading">MENU PRINCIPAL</div><nav className="side-nav">{navigation.slice(0,5).map(([path,label,Icon])=><NavLink key={path} to={path} end={path==='/app'} className={({isActive})=>`nav-item ${isActive?'active':''}`}><Icon size={19}/><span>{label}</span>{path==='/app'&&<span className="nav-active-indicator"/>}</NavLink>)}</nav><div className="nav-heading second">PREFERÊNCIAS</div><nav className="side-nav">{navigation.slice(5).map(([path,label,Icon])=><NavLink key={path} to={path} className={({isActive})=>`nav-item ${isActive?'active':''}`}><Icon size={19}/><span>{label}</span></NavLink>)}</nav><div className="sidebar-bottom"><div className="side-help"><span><Sparkles size={21}/></span><h4>Proteção começa aqui.</h4><p>Acompanhe sua segurança de forma simples.</p></div><button className="sidebar-user" onClick={()=>navigate('/app/configuracoes')}><span className="user-avatar">{user?.name?.charAt(0).toUpperCase()}</span><span><strong>{user?.name}</strong><small>{user?.email}</small></span><ChevronRight size={16}/></button></div></aside><div className="main-area"><header className="topbar"><button className="icon-btn mobile-hamburger" aria-label="Abrir menu" onClick={()=>setMobile(true)}><Menu size={23}/></button><div className="breadcrumbs"><span>Meu espaço</span><ChevronRight size={14}/><strong>{navigation.find(([path])=>path===location.pathname)?.[1]||'Segurança'}</strong></div><div className="top-actions"><span className="top-security"><span/> Ambiente protegido</span><Link className="top-icon" to="/app/notificacoes" aria-label="Notificações"><Bell size={20}/></Link><button className="top-icon" aria-label="Sair" onClick={()=>void logout().then(()=>navigate('/'))}><LogOut size={19}/></button><span className="user-avatar top-user">{user?.name?.charAt(0).toUpperCase()}</span></div></header><main className="content"><motion.div key={location.pathname} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{duration:.23}}>{children}</motion.div></main><footer className="app-footer"><span>CoFree © 2026 · Vela</span><span><ShieldCheck size={14}/> Proteção com transparência</span></footer></div></div>}
function Protected({children}:{children:ReactNode}){const{user,loading}=useAuth();if(loading)return <div className="full-loader"><LoaderCircle size={34} className="spin"/> Carregando seu espaço...</div>;if(!user)return <Navigate to="/entrar" replace/>;return <AppShell>{children}</AppShell>}

function DashboardPage(){const{user}=useAuth();const {data,isLoading,error}=useQuery({queryKey:['dashboard'],queryFn:()=>api<Dashboard>('/dashboard')});return <><Heading eyebrow="CENTRAL DE SEGURANÇA" title={`Olá, ${user?.name?.split(' ')[0]} 👋`} description="Aqui está o panorama da segurança das suas contas digitais." action={<Link className="btn btn-primary" to="/app/emails"><Plus size={17}/> Monitorar e-mail</Link>}/>{error&&<Alert message={getError(error)}/>}<div className="welcome-banner"><div><span className="banner-eyebrow"><Sparkles size={15}/> VISÃO GERAL DA SUA PROTEÇÃO</span><h2>Mais clareza sobre o que importa.</h2><p>Seus dados de segurança organizados para você tomar melhores decisões, com tranquilidade.</p><Link to="/app/emails" className="banner-link">Ver meus monitoramentos <ArrowRight size={16}/></Link></div><div className="banner-shield"><ShieldCheck size={104} strokeWidth={1.2}/></div></div><div className="stats-grid"><StatCard title="E-mails monitorados" value={data?.monitored_emails} loading={isLoading} icon={AtSign} caption="Endereços adicionados" color="blue"/><StatCard title="Exposições conhecidas" value={data?.exposures} loading={isLoading} icon={ShieldAlert} caption={data?.exposures?'Atenção recomendada':'Nas contas monitoradas'} color="red"/><StatCard title="Senhas no Vault" value={data?.vault_items} loading={isLoading} icon={LockKeyhole} caption="Credenciais criptografadas" color="purple"/><StatCard title="Verificações pendentes" value={data?.pending_checks} loading={isLoading} icon={Activity} caption="Inclui consultas indisponíveis" color="amber"/></div><section className="panel posture-panel"><div className="posture-header"><div><span className="eyebrow"><Activity size={14}/> POSTURA DE SEGURANÇA</span><h2>Visão dos monitoramentos</h2><p>Distribuição dos estados conhecidos, calculada sobre todos os e-mails cadastrados.</p></div><Link to="/app/configuracoes" className="btn btn-soft"><Settings size={16}/> Configurar frequência</Link></div>
 <div className="posture-bars" role="img" aria-label={`E-mails sem exposições conhecidas: ${data?.email_health?.clear??0}; com exposições: ${data?.email_health?.exposed??0}; pendentes ou indisponíveis: ${data?.pending_checks??0}`}>
 {[{label:'Sem exposições conhecidas',value:data?.email_health?.clear??0,tone:'safe'},
 {label:'Com exposições conhecidas',value:data?.email_health?.exposed??0,tone:'risk'},
 {label:'Pendentes ou indisponíveis',value:data?.pending_checks??0,tone:'wait'}].map(row=><div key={row.label} className="posture-row"><div><span>{row.label}</span><strong>{row.value}</strong></div>
 <div className="posture-track"><span className={`posture-fill fill-${row.tone}`} style={{width:`${data?.monitored_emails?row.value/data.monitored_emails*100:0}%`}}/></div></div>)}
 </div><p className="posture-footnote"><Info size={14}/> Um resultado sem correspondência não garante que o e-mail esteja seguro; a consulta depende da base disponível.</p></section><div className="dashboard-bottom"><section className="panel"><div className="panel-head"><div><h2>Contas monitoradas</h2><p>Status de seus endereços cadastrados</p></div><Link to="/app/emails" className="panel-more">Ver tudo <ArrowRight size={15}/></Link></div>{isLoading?<div className="loading-lines"><i/><i/><i/></div>:data?.emails.length?<div className="email-list">{data.emails.map(m=><div className="email-row" key={m.id}><span className="email-icon"><AtSign size={19}/></span><div><strong>{m.email}</strong><small>Última verificação: {fmt(m.last_checked)}</small></div><Tag status={m.status}/></div>)}</div>:<Empty icon={AtSign} title="Comece pelo seu primeiro e-mail" description="Cadastre um endereço para acompanhar possíveis exposições de dados." action={<Link className="btn btn-soft" to="/app/emails"><Plus size={16}/> Adicionar e-mail</Link>}/>}</section><section className="panel insights"><div className="panel-head"><div><h2>Central de atenção</h2><p>O que merece sua atenção</p></div><ShieldCheck size={21} className="purple-text"/></div>{data?.notifications.length?data.notifications.map(n=><div className="insight-row" key={n.id}><span className="insight-icon"><Bell size={17}/></span><div><strong>{n.title}</strong><p>{n.message}</p></div></div>):<div className="insight-row"><span className="insight-icon"><Info size={18}/></span><div><strong>Ative seus monitoramentos</strong><p>Adicione seus e-mails para receber alertas quando houver novas exposições conhecidas.</p></div></div>}<div className="insight-row"><span className="insight-icon violet"><Lock size={17}/></span><div><strong>Proteja suas credenciais</strong><p>Use senhas únicas e ative autenticação em dois fatores sempre que possível.</p></div></div><Link to="/app/vault" className="insight-link">Acessar meu Vault <ArrowUpRight size={16}/></Link></section></div></>}
function StatCard({title,value,icon:Icon,caption,color,loading}:{title:string;value?:number;icon:IconType;caption:string;color:string;loading:boolean}){return <div className="stat-card"><div className={`stat-icon ${color}`}><Icon size={20}/></div><span className="stat-title">{title}</span><strong className="stat-value">{loading?'—':value??'—'}</strong><div className="stat-caption"><span className={`caption-dot ${color}`}/>{caption}</div></div>}

function EmailsPage(){const qc=useQueryClient(),[email,setEmail]=useState(''),[adding,setAdding]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[selected,setSelected]=useState<Monitor|null>(null),[confirm,setConfirm]=useState<Monitor|null>(null);const {data=[],isLoading}=useQuery({queryKey:['emails'],queryFn:()=>api<Monitor[]>('/emails')});const history=useQuery({queryKey:['email-history',selected?.id],queryFn:()=>api<{checks:{id:string;status:string;detail:string;created_at:string}[];exposures:{id:string;breach_name:string;discovered_at:string}[]}>(`/emails/${selected!.id}/history`),enabled:!!selected});const mutate=async(fn:()=>Promise<unknown>,msg:string)=>{setError('');try{await fn();setMessage(msg);setEmail('');setAdding(false);setConfirm(null);await Promise.all([qc.invalidateQueries({queryKey:['emails']}),qc.invalidateQueries({queryKey:['dashboard']}),qc.invalidateQueries({queryKey:['email-history']})]);}catch(e){setError(getError(e))}};return <><Heading eyebrow="MONITORAMENTO DE DADOS" title="Meus e-mails" description="Acompanhe possíveis exposições conhecidas dos endereços importantes para você." action={<Button onClick={()=>setAdding(true)}><Plus size={17}/> Adicionar e-mail</Button>}/>{error&&<Alert message={error}/>} {message&&<Alert kind="success" message={message}/>}<div className="notice-bar"><Info size={19}/><p>Os resultados dependem da disponibilidade da API de vazamentos. Uma verificação não realizada <strong>não significa que o e-mail está seguro</strong>.</p></div><div className="panel"><div className="panel-head"><div><h2>Endereços cadastrados</h2><p>{data.length} de 25 e-mails monitorados</p></div><span className="count-circle">{data.length}</span></div>{isLoading?<div className="loading-lines"><i/><i/><i/></div>:data.length?<div className="email-table"><div className="table-heading"><span>ENDEREÇO</span><span>STATUS</span><span>CONSULTAS</span><span>AÇÕES</span></div>{data.map(m=><div className="table-row" key={m.id}><div className="td-email"><span className="email-icon"><AtSign size={19}/></span><strong>{m.email}</strong></div><div><Tag status={m.status}/></div><div className="muted-text">Última: {fmt(m.last_checked)}<br/>Próxima: {m.next_check?fmt(m.next_check):"Sem agendamento"}</div><div className="table-actions"><button title="Ver histórico" aria-label={`Histórico de ${m.email}`} onClick={()=>setSelected(m)}><FileClock size={18}/></button><button title="Verificar" aria-label={`Verificar ${m.email}`} onClick={()=>void mutate(()=>api(`/emails/${m.id}/scan`,{method:'POST'}),'Verificação enviada para a fila')}><RefreshCw size={18}/></button><button title="Remover" aria-label={`Remover ${m.email}`} onClick={()=>setConfirm(m)}><Trash2 size={18}/></button></div></div>)}</div>:<Empty icon={AtSign} title="Nenhum e-mail cadastrado" description="Adicione seus endereços para começar a acompanhar vazamentos conhecidos." action={<Button onClick={()=>setAdding(true)}><Plus size={16}/> Adicionar primeiro e-mail</Button>}/>}</div><AnimatePresence>{adding&&<Modal title="Adicionar e-mail" onClose={()=>setAdding(false)}><p className="muted">Cadastre um endereço para monitorar. As verificações dependem da disponibilidade e dos limites da API XposedOrNot.</p><form onSubmit={e=>{e.preventDefault();void mutate(()=>api('/emails',{method:'POST',body:JSON.stringify({email})}),'E-mail adicionado com sucesso')}}><Field label="Endereço de e-mail" type="email" value={email} onChange={setEmail} placeholder="voce@exemplo.com" required/><div className="modal-actions"><Button kind="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button type="submit"><Plus size={16}/> Cadastrar e-mail</Button></div></form></Modal>}{confirm&&<Modal title="Remover monitoramento?" onClose={()=>setConfirm(null)}><p className="muted">O endereço <strong>{confirm.email}</strong>, suas verificações e exposições associadas serão excluídos.</p><div className="modal-actions"><Button kind="ghost" onClick={()=>setConfirm(null)}>Cancelar</Button><Button kind="danger" onClick={()=>void mutate(()=>api(`/emails/${confirm.id}`,{method:'DELETE'}),'Monitoramento removido')}><Trash2 size={16}/> Excluir</Button></div></Modal>}{selected&&<Modal title="Histórico de verificações" onClose={()=>setSelected(null)}><p className="muted">{selected.email}</p>{history.isLoading?<p>Carregando histórico...</p>:history.error?<Alert message={getError(history.error)}/>:<div className="history-box"><h3>Exposições conhecidas</h3>{history.data?.exposures.length?history.data.exposures.map(x=><div key={x.id} className="history-line"><ShieldAlert size={17}/> <strong>{x.breach_name}</strong><span>{fmt(x.discovered_at)}</span></div>):<p className="muted">Nenhuma exposição registrada.</p>}<h3>Consultas realizadas</h3>{history.data?.checks.length?history.data.checks.map(c=><div className="history-line" key={c.id}><Clock size={17}/><span>{c.detail||statusLabel[c.status]}</span><time>{fmt(c.created_at)}</time></div>):<p className="muted">Nenhuma consulta registrada.</p>}</div>}</Modal>}</AnimatePresence></>}

function NoticesPage(){const qc=useQueryClient(),{data=[],isLoading,error}=useQuery({queryKey:['notifications'],queryFn:()=>api<Notice[]>('/notifications')});return <><Heading eyebrow="ATUALIZAÇÕES DE SEGURANÇA" title="Notificações" description="Alertas e avisos importantes sobre suas contas monitoradas."/>{error&&<Alert message={getError(error)}/>}<div className="panel">{isLoading?<div className="loading-lines"><i/><i/><i/></div>:data.length?data.map(n=><div className={`notification-row ${n.read?'read':''}`} key={n.id}><div className="insight-icon"><Bell size={19}/></div><div><h3>{n.title}</h3><p>{n.message}</p><small>{fmt(n.created_at)}</small></div>{!n.read&&<Button kind="soft" onClick={()=>void api(`/notifications/${n.id}/read`,{method:'POST'}).then(()=>qc.invalidateQueries({queryKey:['notifications']}))}><Check size={16}/> Marcar lida</Button>}</div>):<Empty icon={Bell} title="Tudo em dia por aqui" description="Seus novos alertas e recomendações aparecerão neste espaço."/>}</div></>}

const emptyEntry:SecretEntry={name:'',username:'',password:'',website:'',notes:'',category:'Pessoal',favorite:false};
function VaultPage(){const {user}=useAuth();const qc=useQueryClient(),{data:config,isLoading}=useQuery({queryKey:['vault-config'],queryFn:()=>api<VaultConfig|null>('/vault/config')});const {data:stored=[]}=useQuery({queryKey:['vault-items'],queryFn:()=>api<VaultCiphertext[]>('/vault/items'),enabled:!!config});const[key,setKey]=useState<Uint8Array|null>(null),[password,setPassword]=useState(''),[passwordConfirm,setPasswordConfirm]=useState(''),[recoveryCode,setRecoveryCode]=useState(''),[showRecovery,setShowRecovery]=useState(false),[recoverMode,setRecoverMode]=useState(false),[entries,setEntries]=useState<{id:string;data:SecretEntry}[]>([]),[active,setActive]=useState<{id?:string;data:SecretEntry}|null>(null),[query,setQuery]=useState(''),[error,setError]=useState(''),[success,setSuccess]=useState(''),[busy,setBusy]=useState(false),[reveal,setReveal]=useState<Record<string,boolean>>({}),[newCode,setNewCode]=useState(''),[deleteTarget,setDeleteTarget]=useState<string|null>(null);
 const lock=()=>{if(key)key.fill(0);setKey(null);setEntries([]);setPassword('');setRecoveryCode('');};
 useEffect(()=>{if(!key)return;let id=window.setTimeout(lock,10*60*1000);const reset=()=>{clearTimeout(id);id=window.setTimeout(lock,10*60*1000)};window.addEventListener('click',reset);window.addEventListener('keydown',reset);return()=>{clearTimeout(id);window.removeEventListener('click',reset);window.removeEventListener('keydown',reset)}},[key]);
 useEffect(()=>{if(!key)return;let alive=true;Promise.all(stored.map(async entry=>({id:entry.id,data:await decryptItem(entry,key,user!.id)}))).then(items=>{if(alive){setEntries(items);setError('')}}).catch(()=>{if(alive)setError('Falha ao descriptografar dados. O conteúdo pode ter sido alterado ou a chave está incorreta.')});return()=>{alive=false}},[key,stored]);
 const run=async(task:()=>Promise<void>)=>{setBusy(true);setError('');setSuccess('');try{await task()}catch(e){setError(getError(e))}finally{setBusy(false)}};
 const start=()=>void run(async()=>{if(password!==passwordConfirm)throw Error('As senhas mestras não coincidem');const created=await createVault(password);await api('/vault/config',{method:'POST',body:JSON.stringify(created.config)});setKey(created.vaultKey);setNewCode(created.recoveryCode);setShowRecovery(true);setPassword('');setPasswordConfirm('');await qc.invalidateQueries({queryKey:['vault-config']})});
 const unlock=()=>void run(async()=>{if(!config)throw Error('Configuração indisponível');const unlocked=recoverMode?await recoverVault(config,recoveryCode):await unlockVault(config,password);setKey(unlocked);setPassword('');setRecoveryCode('');setRecoverMode(false)});
 const saveEntry=()=>void run(async()=>{if(!key||!active)throw Error('Cofre bloqueado');if(!active.data.name.trim()||!active.data.password)throw Error('Preencha serviço e senha');const itemId=active.id||crypto.randomUUID();const cipher=await encryptItem(active.data,key,itemId,user!.id);await api(`/vault/items${active.id?`/${active.id}`:''}`,{method:active.id?'PUT':'POST',body:JSON.stringify(cipher)});setActive(null);await Promise.all([qc.invalidateQueries({queryKey:['vault-items']}),qc.invalidateQueries({queryKey:['dashboard']})]);setSuccess('Credencial armazenada de forma criptografada')});
 const deleteEntry=(id:string)=>void run(async()=>{await api(`/vault/items/${id}`,{method:'DELETE'});await qc.invalidateQueries({queryKey:['vault-items']});setDeleteTarget(null);setActive(null);setSuccess('Credencial removida')});
 const {data:monitorSettings}=useQuery({queryKey:['monitoring-preferences'],queryFn:()=>api<MonitoringPreferences>('/monitoring/preferences'),enabled:!!user});
 const [localScan,setLocalScan]=useState<LocalPasswordScan|null>(()=>user?readLocalScan(user.id):null);
 const [scanBusy,setScanBusy]=useState(false),[scanError,setScanError]=useState('');
 useEffect(()=>{if(!user)return;setLocalScan(readLocalScan(user.id))},[user?.id]);
 useEffect(()=>{
   if(!key || !user || !monitorSettings?.password_enabled || !entries.length || stored.length!==entries.length) return;
   let cancelled=false, inFlight=false;
   const checkDue=async()=>{
     if(inFlight || cancelled || document.visibilityState==='hidden')return;
     const recent=readLocalScan(user.id);
     if(recent && Date.now()-Date.parse(recent.checked_at)<intervalMs[monitorSettings.password_interval])return;
     inFlight=true;setScanBusy(true);setScanError('');
     try{
       // Secrets are decrypted only in this browser; requests disclose a SHA-1 prefix, never a password.
       const unique=[...new Set(entries.map(entry=>entry.data.password).filter(Boolean))];
       const compromisedSecrets=new Set<string>();
       for(const secret of unique){if(cancelled)return;const result=await pwnedPassword(secret);if(result.count>0)compromisedSecrets.add(secret)}
       if(!cancelled){const record={checked_at:new Date().toISOString(),checked:entries.length,compromised:entries.filter(entry=>compromisedSecrets.has(entry.data.password)).length};
         localStorage.setItem(`cofree:password-monitor:${user.id}`,JSON.stringify(record));setLocalScan(record);
       }
     }catch(err){if(!cancelled)setScanError(`Não foi possível verificar todas as senhas: ${getError(err)}`)}
     finally{inFlight=false;if(!cancelled)setScanBusy(false)}
   };
   void checkDue();const handleVisible=()=>{if(document.visibilityState==='visible')void checkDue()};
   document.addEventListener('visibilitychange',handleVisible);
   const timer=window.setInterval(()=>void checkDue(),60000);
   return()=>{cancelled=true;clearInterval(timer);document.removeEventListener('visibilitychange',handleVisible)};
 },[key,user?.id,monitorSettings?.password_enabled,monitorSettings?.password_interval,entries,stored.length]);
 const filtered=useMemo(()=>entries.filter(({data})=>`${data.name} ${data.username} ${data.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(b.data.favorite)-Number(a.data.favorite)),[entries,query]);
 if(isLoading)return <div className="full-loader"><LoaderCircle className="spin"/> Preparando Vault...</div>;
 return <><Heading eyebrow="SEUS SEGREDOS, SÓ SEUS" title="Meu Vault" description="Armazene e gerencie suas credenciais com criptografia ponta a ponta no navegador." action={key?<div className="heading-action"><Button kind="soft" onClick={lock}><Lock size={16}/> Bloquear</Button><Button onClick={()=>setActive({data:{...emptyEntry}})}><Plus size={16}/> Nova credencial</Button></div>:null}/>{error&&<Alert message={error}/>} {success&&<Alert message={success} kind="success"/>}{!config?<div className="vault-gate"><span className="vault-gate-icon"><LockKeyhole size={39}/></span><span className="eyebrow">PRIMEIRO ACESSO</span><h2>Um cofre que só você pode abrir.</h2><p>Crie sua senha mestra. Ela nunca será enviada aos nossos servidores. Se você perdê-la e também perder a chave de recuperação, não será possível restaurar suas credenciais.</p><div className="gate-fields"><Field label="Senha mestra (mínimo 12 caracteres)" type="password" value={password} onChange={setPassword} placeholder="Crie uma senha mestra forte"/><Field label="Confirme a senha mestra" type="password" value={passwordConfirm} onChange={setPasswordConfirm} placeholder="Repita sua senha"/><Button onClick={start} loading={busy} disabled={password.length<12}><LockKeyhole size={17}/> Criar Vault seguro</Button></div></div>:!key?<div className="vault-gate"><span className="vault-gate-icon"><LockKeyhole size={39}/></span><span className="eyebrow">VAULT BLOQUEADO</span><h2>Bem-vindo ao seu espaço privado.</h2><p>{recoverMode?'Use sua chave de recuperação para desbloquear seu cofre neste dispositivo.':'Digite sua senha mestra para descriptografar suas credenciais exclusivamente neste dispositivo.'}</p><form className="gate-fields" onSubmit={e=>{e.preventDefault();unlock()}}><Field label={recoverMode?'Chave de recuperação':'Senha mestra'} value={recoverMode?recoveryCode:password} onChange={recoverMode?setRecoveryCode:setPassword} type={recoverMode?'text':'password'} placeholder={recoverMode?'Cole a chave de recuperação':'Sua senha mestra'} required/><Button type="submit" loading={busy}><Lock size={17}/> Desbloquear meu cofre</Button><button type="button" className="text-button" onClick={()=>{setRecoverMode(!recoverMode);setError('')}}>{recoverMode?'Usar senha mestra':'Tenho uma chave de recuperação'}</button></form></div>:<><div className="vault-toolbar"><div className="search-input"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar credenciais, categorias..." aria-label="Buscar credenciais"/></div><span className="vault-encryption"><ShieldCheck size={16}/> Criptografia ativa</span></div><div className="vault-info"><Lock size={17}/><span>Todos os dados abaixo são descriptografados somente neste navegador. Seu servidor recebe apenas dados cifrados.</span><Link to="/app/configuracoes">Gerenciar chaves <ArrowUpRight size={14}/></Link></div>{monitorSettings?.password_enabled&&<div className="vault-scan-status"><span><ScanSearch size={18}/><strong>Verificação automática de senhas</strong></span>
 <p>{scanBusy?'Analisando senhas localmente…':localScan?`Última análise: ${fmt(localScan.checked_at)} · ${localScan.checked} senha(s) · ${localScan.compromised} comprometida(s)`:'A análise será iniciada quando o Vault estiver desbloqueado e houver senhas cadastradas.'}</p>
 {!scanBusy && localScan && localScan.compromised>0 && <Alert message={`Atenção: ${localScan.compromised} senha(s) do Vault aparecem em vazamentos conhecidos. Troque-as nos serviços correspondentes.`}/>} {scanError&&<Alert message={scanError}/>}<small>{localScan?`Próxima verificação prevista neste dispositivo: ${fmt(new Date(Date.parse(localScan.checked_at)+intervalMs[monitorSettings.password_interval]).toISOString())}. `:''}A execução depende de manter o Vault desbloqueado nesta página.</small></div>}{filtered.length?<div className="vault-list">{filtered.map(({id,data})=><div className="vault-entry" key={id}><div className="vault-entry-icon">{data.name.charAt(0).toUpperCase()}</div><div className="vault-entry-text"><strong>{data.name}</strong><span>{data.username||data.website||'Sem identificação'}</span></div>{data.favorite&&<Heart size={17} className="favorite-icon" fill="currentColor"/>}<span className="vault-category">{data.category||'Pessoal'}</span><button className="icon-btn" aria-label="Copiar senha" title="Copiar senha" onClick={()=>void navigator.clipboard.writeText(data.password).then(()=>setSuccess('Senha copiada. Limpe sua área de transferência após o uso.'))}><Copy size={18}/></button><Button kind="soft" onClick={()=>setActive({id,data:{...data}})}>Editar <ChevronRight size={15}/></Button></div>)}</div>:<div className="panel"><Empty icon={LockKeyhole} title={query?'Nenhum resultado':'Seu cofre está vazio'} description={query?'Tente outro termo de busca.':'Adicione sua primeira credencial para armazená-la de forma criptografada.'} action={!query?<Button onClick={()=>setActive({data:{...emptyEntry}})}><Plus size={16}/> Adicionar credencial</Button>:null}/></div>}</>}
 <AnimatePresence>{showRecovery&&<Modal title="Guarde sua chave de recuperação" onClose={()=>{setShowRecovery(false);setNewCode('')}}><Alert kind="info" message="Esta chave será exibida uma única vez. Salve-a offline, em local seguro. Sem ela e sem a senha mestra, os dados não poderão ser recuperados."/><div className="recovery-code">{newCode}</div><div className="modal-actions"><Button kind="soft" onClick={()=>void navigator.clipboard.writeText(newCode)}><Copy size={16}/> Copiar chave</Button><Button onClick={()=>{setShowRecovery(false);setNewCode('')}}>Guardei minha chave <Check size={16}/></Button></div></Modal>}{active&&key&&<Modal title={active.id?'Editar credencial':'Nova credencial'} onClose={()=>setActive(null)}><form onSubmit={e=>{e.preventDefault();saveEntry()}} className="entry-form"><Field label="Serviço" value={active.data.name} onChange={v=>setActive({...active,data:{...active.data,name:v}})} placeholder="Ex.: Conta de e-mail" required/><Field label="Usuário ou e-mail" value={active.data.username} onChange={v=>setActive({...active,data:{...active.data,username:v}})} placeholder="usuario@exemplo.com"/><div className="password-input"><Field label="Senha" type={reveal[active.id||'new']?'text':'password'} value={active.data.password} onChange={v=>setActive({...active,data:{...active.data,password:v}})} required><button type="button" className="field-suffix" aria-label="Mostrar/ocultar senha" onClick={()=>setReveal({...reveal,[active.id||'new']:!reveal[active.id||'new']})}>{reveal[active.id||'new']?<EyeOff size={17}/>:<Eye size={17}/>}</button></Field><button type="button" className="text-button" onClick={()=>setActive({...active,data:{...active.data,password:generatePassword()}})}>Gerar senha forte</button></div><Field label="Site (opcional)" value={active.data.website} onChange={v=>setActive({...active,data:{...active.data,website:v}})} placeholder="https://exemplo.com"/><Field label="Categoria" value={active.data.category} onChange={v=>setActive({...active,data:{...active.data,category:v}})} placeholder="Pessoal, Trabalho..."/><label className="check-line"><input type="checkbox" checked={active.data.favorite} onChange={e=>setActive({...active,data:{...active.data,favorite:e.target.checked}})}/> Adicionar aos favoritos</label><label className="field"><span>Observações</span><textarea value={active.data.notes} onChange={e=>setActive({...active,data:{...active.data,notes:e.target.value}})} placeholder="Notas privadas (criptografadas)" rows={3}/></label><div className="modal-actions">{active.id&&<Button kind="danger" onClick={()=>{setDeleteTarget(active.id!);setActive(null)}}><Trash2 size={16}/></Button>}<Button kind="ghost" onClick={()=>setActive(null)}>Cancelar</Button><Button type="submit" loading={busy}><Lock size={16}/> Salvar com criptografia</Button></div></form></Modal>}{deleteTarget&&<Modal title="Excluir credencial?" onClose={()=>setDeleteTarget(null)}><p className="muted">Esta credencial será removida permanentemente do cofre.</p><div className="modal-actions"><Button kind="ghost" onClick={()=>setDeleteTarget(null)}>Cancelar</Button><Button kind="danger" loading={busy} onClick={()=>deleteEntry(deleteTarget)}><Trash2 size={16}/> Excluir</Button></div></Modal>}</AnimatePresence></>;
}

function GeneratorPage(){const[length,setLength]=useState(20),[value,setValue]=useState(()=>generatePassword(20)),[message,setMessage]=useState(''),[checkResult,setCheckResult]=useState(''),[busy,setBusy]=useState(false);const update=(n:number)=>{setLength(n);setValue(generatePassword(n));setCheckResult('')};const verify=async()=>{setBusy(true);setCheckResult('');try{const result=await pwnedPassword(value);setCheckResult(result.count>0?`Esta senha apareceu ${result.count.toLocaleString('pt-BR')} vez(es) em vazamentos conhecidos.`:'Nenhuma correspondência conhecida encontrada. Isso não garante segurança absoluta.')}catch(e){setCheckResult(getError(e))}finally{setBusy(false)}};return <><Heading eyebrow="FERRAMENTAS DE SEGURANÇA" title="Gerador de senhas" description="Crie senhas fortes, aleatórias e exclusivas para suas contas."/><div className="generator-layout"><div className="panel generator-panel"><span className="eyebrow">SENHA GERADA LOCALMENTE</span><div className="generated-password"><code>{value}</code><button title="Copiar senha" onClick={()=>void navigator.clipboard.writeText(value).then(()=>setMessage('Senha copiada para a área de transferência'))}><Copy size={20}/></button></div>{message&&<Alert message={message} kind="success"/>}<div className="range-header"><label htmlFor="password-length">Comprimento da senha</label><strong>{length} caracteres</strong></div><input id="password-length" className="range-input" type="range" min="12" max="40" value={length} onChange={e=>update(Number(e.target.value))}/><div className="generator-actions"><Button onClick={()=>update(length)}><RefreshCw size={17}/> Gerar outra senha</Button><Button kind="soft" loading={busy} onClick={()=>void verify()}><ShieldCheck size={17}/> Checar vazamento</Button></div>{checkResult&&<Alert kind={checkResult.startsWith('Nenhuma')?'success':'info'} message={checkResult}/>}</div><div className="panel generator-tips"><h2>Boas práticas</h2><p>Uma senha forte é apenas parte da sua proteção.</p><div className="tip"><CheckCircle2 size={19}/><span>Use uma senha diferente para cada serviço.</span></div><div className="tip"><CheckCircle2 size={19}/><span>Prefira senhas longas e imprevisíveis.</span></div><div className="tip"><CheckCircle2 size={19}/><span>Ative autenticação em duas etapas.</span></div><div className="tip"><CheckCircle2 size={19}/><span>Armazene as senhas em seu Vault criptografado.</span></div><Link to="/app/vault" className="insight-link">Abrir meu Vault <ArrowRight size={16}/></Link></div></div></>}

const scheduleChoices: {value:MonitoringPreferences['email_interval'];label:string}[] = [
 {value:'1h',label:'A cada 1 hora'}, {value:'24h',label:'A cada 1 dia'},
 {value:'7d',label:'A cada 1 semana'}, {value:'30d',label:'A cada 1 mês'}
];
const intervalMs:Record<MonitoringPreferences['email_interval'],number> = {'1h':3600000,'24h':86400000,'7d':604800000,'30d':2592000000};
type LocalPasswordScan = {checked_at:string;checked:number;compromised:number};
function readLocalScan(userId:string):LocalPasswordScan|null {
 try {const raw=localStorage.getItem(`cofree:password-monitor:${userId}`); if(!raw)return null;
   const parsed=JSON.parse(raw) as LocalPasswordScan;
   return parsed && typeof parsed.checked_at==='string' && Number.isFinite(Date.parse(parsed.checked_at)) && Number.isFinite(parsed.checked) && Number.isFinite(parsed.compromised) ? parsed:null;
 } catch {return null;}
}

function PasswordCheckerPage(){
 const [value,setValue]=useState(''),[visible,setVisible]=useState(false),[busy,setBusy]=useState(false);
 const [result,setResult]=useState<{count:number}|null>(null),[error,setError]=useState('');
 const check=async(e:FormEvent)=>{e.preventDefault();if(!value.trim())return;setBusy(true);setResult(null);setError('');
   try{const {count}=await pwnedPassword(value);setResult({count});setValue('')}catch(err){setError(getError(err))}finally{setBusy(false)}
 };
 return <><Heading eyebrow="INTELIGÊNCIA DE CREDENCIAIS" title="Verificador de senhas" description="Descubra se uma senha aparece em bases de vazamentos conhecidos. A verificação acontece com privacidade no navegador."/>
 <div className="checker-grid"><section className="panel checker-main"><span className="eyebrow"><Fingerprint size={14}/> ANÁLISE PRIVADA</span>
 <h2>Uma senha comprometida não deveria ser um segredo.</h2><p>Digite uma senha para consultar a base Pwned Passwords. Só os primeiros cinco caracteres de seu hash SHA-1 saem do dispositivo.</p>
 <form onSubmit={e=>void check(e)}><label className="field"><span>Senha a verificar</span><div className="field-wrap">
 <input type={visible?'text':'password'} value={value} onChange={e=>{setValue(e.target.value);setResult(null);setError('')}} autoComplete="off" spellCheck={false} placeholder="Digite a senha para analisar" required />
 <button type="button" className="field-suffix" aria-label={visible?'Ocultar senha':'Mostrar senha'} onClick={()=>setVisible(!visible)}>{visible?<EyeOff size={18}/>:<Eye size={18}/>}</button>
 </div></label><Button type="submit" loading={busy} disabled={!value}><ScanSearch size={17}/> Verificar exposição</Button></form>
 {error&&<Alert message={error}/>} {result&&<div className={`scan-result ${result.count?'scan-danger':'scan-safe'}`} role="status">
 {result.count?<ShieldAlert size={28}/>:<ShieldCheck size={28}/>}<div><strong>{result.count?'Senha encontrada em vazamentos':'Nenhuma exposição conhecida'}</strong>
 <p>{result.count?`Encontrada ${result.count.toLocaleString('pt-BR')} vez(es). Não use esta senha: altere-a onde estiver cadastrada.`:'Nenhuma correspondência foi encontrada. Isso não comprova que a senha seja segura ou exclusiva.'}</p></div></div>}
 </section><aside className="panel checker-aside"><div className="checker-symbol"><ShieldCheck size={35}/></div><h3>Privacidade em cada consulta</h3>
 <div className="privacy-step"><span>01</span><p>A senha é transformada em hash SHA-1 localmente.</p></div>
 <div className="privacy-step"><span>02</span><p>Somente um prefixo de 5 caracteres vai à API.</p></div>
 <div className="privacy-step"><span>03</span><p>A comparação final acontece no navegador.</p></div>
 <div className="notice-bar"><Info size={17}/>Não guardamos a senha digitada; evite verificar senhas em computadores públicos.</div>
 <Link to="/app/vault" className="insight-link">Ir para o Vault <ArrowRight size={16}/></Link></aside></div></>
}

function MonitoringSettings(){
 const qc=useQueryClient(),{data:pref,isLoading,error}=useQuery({queryKey:['monitoring-preferences'],queryFn:()=>api<MonitoringPreferences>('/monitoring/preferences')});
 const [draft,setDraft]=useState<MonitoringPreferences|null>(null),[saving,setSaving]=useState(false),[message,setMessage]=useState(''),[err,setErr]=useState('');
 useEffect(()=>{if(pref)setDraft(pref)},[pref]);
 const settings=draft??pref;
 const update=(patch:Partial<MonitoringPreferences>)=>setDraft(old=>({...((old??pref) as MonitoringPreferences),...patch}));
 const save=async()=>{if(!settings)return;setSaving(true);setErr('');setMessage('');try{
   await api<MonitoringPreferences>('/monitoring/preferences',{method:'PUT',body:JSON.stringify(settings)});
   await Promise.all([qc.invalidateQueries({queryKey:['monitoring-preferences']}),qc.invalidateQueries({queryKey:['emails']})]);
   setMessage('Frequências e monitoramentos atualizados.');
 }catch(e){setErr(getError(e))}finally{setSaving(false)}};
 return <section className="panel monitoring-section"><div className="section-icon"><Activity size={22}/></div>
 <h2>Monitoramento automático</h2><p>Controle quais dados serão analisados e com que frequência. As frequências são independentes.</p>
 {isLoading&&<div className="loading-lines"><i/><i/></div>}{error&&<Alert message={getError(error)}/>}
 {settings&&<><div className="monitoring-control"><label className="toggle-row"><span><strong><AtSign size={17}/> E-mails</strong><small>Verificação pelo servidor, inclusive quando o site estiver fechado.</small></span>
 <input type="checkbox" checked={settings.email_enabled} onChange={e=>update({email_enabled:e.target.checked})} aria-label="Ativar monitoramento automático de e-mails"/></label>
 <label className="field"><span>Frequência dos e-mails</span><select aria-label="Frequência de e-mails" value={settings.email_interval} disabled={!settings.email_enabled} onChange={e=>update({email_interval:e.target.value as MonitoringPreferences['email_interval']})}>
 {scheduleChoices.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></label></div>
 <div className="monitoring-control"><label className="toggle-row"><span><strong><KeyRound size={17}/> Senhas do Vault</strong><small>Verificação somente no navegador, com o Vault desbloqueado.</small></span>
 <input type="checkbox" checked={settings.password_enabled} onChange={e=>update({password_enabled:e.target.checked})} aria-label="Ativar monitoramento automático de senhas"/></label>
 <label className="field"><span>Frequência das senhas</span><select aria-label="Frequência de senhas" value={settings.password_interval} disabled={!settings.password_enabled} onChange={e=>update({password_interval:e.target.value as MonitoringPreferences['password_interval']})}>
 {scheduleChoices.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></label></div>
 <p className="monitor-privacy"><ShieldCheck size={16}/> A verificação automática de senhas não funciona com o site fechado ou o Vault bloqueado. Não armazenamos senhas nem hashes completos para viabilizar checagem remota.</p>
 {err&&<Alert message={err}/>} {message&&<Alert message={message} kind="success"/>}
 <Button loading={saving} onClick={()=>void save()}><Check size={17}/> Salvar monitoramentos</Button></>}
 </section>
}

function SessionsPage(){type Sess={id:string;user_agent:string;current:boolean;created_at:string;last_seen:string;expires_at:string;revoked:boolean};const qc=useQueryClient(),{data=[],error,isLoading}=useQuery({queryKey:['sessions'],queryFn:()=>api<Sess[]>('/auth/sessions')});const [message,setMessage]=useState(''),[err,setErr]=useState('');const change=async(path:string,method='DELETE')=>{try{await api(path,{method});setMessage('Sessão revogada com sucesso');await qc.invalidateQueries({queryKey:['sessions']});if(path.includes('/sessions')&&!path.includes('others=true')&&(path.endsWith('/sessions')||data.find(x=>x.id===path.split('/').at(-1))?.current)){window.location.assign('/entrar')}}catch(e){setErr(getError(e))}};return <><Heading eyebrow="CONTROLE DE ACESSO" title="Sessões e dispositivos" description="Veja onde sua conta foi acessada e encerre sessões que você não reconhece." action={<Button kind="soft" onClick={()=>void change('/auth/sessions?others=true')}>Encerrar outras sessões</Button>}/>{err&&<Alert message={err}/>} {message&&<Alert message={message} kind="success"/>}{error&&<Alert message={getError(error)}/>}<div className="panel sessions-panel">{isLoading?<div className="loading-lines"><i/><i/></div>:data.length?data.map(x=><div className="session-row" key={x.id}><span className="session-icon"><MonitorSmartphone size={23}/></span><div><div className="session-title"><strong>{x.user_agent.slice(0,85)}</strong>{x.current&&<span className="tag tag-success">Esta sessão</span>}{x.revoked&&<span className="tag tag-warning">Revogada</span>}</div><p>Iniciada em {fmt(x.created_at)}</p><small>Última atividade: {fmt(x.last_seen)}</small></div>{!x.revoked&&<Button kind="soft" onClick={()=>void change(`/auth/sessions/${x.id}`)}>Revogar</Button>}</div>):<Empty icon={MonitorSmartphone} title="Nenhuma sessão encontrada" description="As sessões aparecerão aqui quando você acessar sua conta."/>}</div><div className="notice-bar"><Shield size={19}/>Se notar um acesso desconhecido, revogue a sessão e altere sua senha imediatamente.</div></>}

function SettingsPage(){const{user,refresh}=useAuth(),[name,setName]=useState(user?.name||''),[notify,setNotify]=useState(user?.notify_exposures??true),[oldPassword,setOldPassword]=useState(''),[password,setPassword]=useState(''),[deletePassword,setDeletePassword]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState(''),[modal,setModal]=useState(false),[vaultPass,setVaultPass]=useState(''),[vaultNewPass,setVaultNewPass]=useState(''),[vaultCode,setVaultCode]=useState(''),[mode,setMode]=useState<'password'|'rotate'>('password');const navigate=useNavigate();const {data:config}=useQuery({queryKey:['vault-config'],queryFn:()=>api<VaultConfig|null>('/vault/config')});const execute=async(fn:()=>Promise<unknown>,success:string):Promise<boolean>=>{setError('');setMessage('');try{await fn();setMessage(success);await refresh();return true}catch(e){setError(getError(e));return false}};const rotate=async()=>{if(!config)throw Error('Vault não criado');const key=await unlockVault(config,vaultPass);try{const updated=await rewrapVault(config,key,vaultNewPass,vaultCode||undefined);await api('/vault/config',{method:'PUT',body:JSON.stringify(updated)})}finally{key.fill(0)}setVaultPass('');setVaultNewPass('');setVaultCode('')};return <><Heading eyebrow="PERSONALIZAÇÃO E PRIVACIDADE" title="Configurações" description="Gerencie seus dados pessoais e as preferências de segurança da sua conta."/><MonitoringSettings/>{error&&<Alert message={error}/>} {message&&<Alert message={message} kind="success"/>}<div className="settings-grid"><section className="panel settings-section"><div className="section-icon"><UserRound size={21}/></div><h2>Informações pessoais</h2><p>Atualize o nome exibido em sua conta.</p><form onSubmit={e=>{e.preventDefault();void execute(()=>api('/auth/me',{method:'PATCH',body:JSON.stringify({name})}),'Perfil atualizado')}}><Field label="Nome completo" value={name} onChange={setName}/><Field label="E-mail cadastrado" value={user?.email||''} onChange={()=>{}}/><Button type="submit">Salvar alterações <ArrowRight size={16}/></Button></form></section><section className="panel settings-section"><div className="section-icon violet"><Bell size={21}/></div><h2>Notificações</h2><p>Decida como deseja receber alertas.</p><label className="toggle-row"><span><strong>Alertas de novas exposições</strong><small>Receber avisos quando o sistema identificar vazamentos</small></span><input type="checkbox" checked={notify} onChange={e=>setNotify(e.target.checked)}/></label><Button onClick={()=>void execute(()=>api('/auth/preferences',{method:'PATCH',body:JSON.stringify({notify_exposures:notify})}),'Preferências atualizadas')}>Salvar preferências</Button></section><section className="panel settings-section"><div className="section-icon amber"><KeyRound size={21}/></div><h2>Senha de acesso</h2><p>A alteração encerrará todas as sessões existentes.</p><form onSubmit={e=>{e.preventDefault();void execute(()=>api('/auth/password/change',{method:'POST',body:JSON.stringify({current_password:oldPassword,new_password:password})}),'Senha alterada. Entre novamente.').then(ok=>{if(ok)navigate('/entrar')})}}><Field label="Senha atual" type="password" value={oldPassword} onChange={setOldPassword}/><Field label="Nova senha (12+ caracteres)" type="password" value={password} onChange={setPassword}/><Button type="submit">Alterar senha <ArrowRight size={16}/></Button></form></section><section className="panel settings-section"><div className="section-icon"><LockKeyhole size={21}/></div><h2>Recuperação do Vault</h2><p>A senha mestra é independente da sua senha de acesso. A recuperação depende exclusivamente da chave criada no seu dispositivo.</p>{config?<><span className="tag tag-success">Vault configurado</span><Button kind="soft" onClick={()=>setMode('rotate')}>Alterar senha mestra / chave</Button></>:<Link to="/app/vault" className="btn btn-soft">Criar Vault <ArrowRight size={16}/></Link>}</section></div><section className="panel danger-section"><div><h2>Exclusão da conta</h2><p>Exclui seus dados, monitoramentos, histórico e o conteúdo cifrado do Vault. Essa ação não pode ser desfeita.</p></div><Button kind="danger" onClick={()=>setModal(true)}>Excluir minha conta <Trash2 size={16}/></Button></section><AnimatePresence>{modal&&<Modal title="Excluir conta permanentemente" onClose={()=>setModal(false)}><Alert message="Essa operação é irreversível. Todas as credenciais criptografadas e os registros associados serão eliminados."/><Field label="Confirme sua senha atual" type="password" value={deletePassword} onChange={setDeletePassword}/><div className="modal-actions"><Button kind="ghost" onClick={()=>setModal(false)}>Cancelar</Button><Button kind="danger" onClick={()=>void execute(()=>api('/auth/me',{method:'DELETE',body:JSON.stringify({current_password:deletePassword})}),'Conta excluída').then(ok=>{if(ok)navigate('/')})}>Excluir definitivamente</Button></div></Modal>}{mode==='rotate'&&<Modal title="Alterar senha mestra do Vault" onClose={()=>setMode('password')}><p className="muted">O navegador abre sua chave atual e a protege novamente com a nova senha. Não enviamos nenhuma chave em texto puro.</p><Field label="Senha mestra atual" type="password" value={vaultPass} onChange={setVaultPass}/><Field label="Nova senha mestra (12+ caracteres)" type="password" value={vaultNewPass} onChange={setVaultNewPass}/><Field label="Chave de recuperação atual (opcional, para manter a existente deixe vazio)" value={vaultCode} onChange={setVaultCode}/><div className="modal-actions"><Button kind="ghost" onClick={()=>setMode('password')}>Cancelar</Button><Button onClick={()=>void execute(rotate,'Proteção das chaves atualizada').then(ok=>{if(ok)setMode('password')})}>Atualizar chaves</Button></div></Modal>}</AnimatePresence></>}

export default function App(){return <Routes><Route path="/" element={<Landing/>}/><Route path="/entrar" element={<AuthPage mode="login"/>}/><Route path="/cadastro" element={<AuthPage mode="register"/>}/><Route path="/esqueci-senha" element={<AuthPage mode="forgot"/>}/><Route path="/redefinir-senha" element={<AuthPage mode="reset"/>}/><Route path="/verificar-email" element={<AuthPage mode="verify"/>}/><Route path="/app" element={<Protected><DashboardPage/></Protected>}/><Route path="/app/emails" element={<Protected><EmailsPage/></Protected>}/><Route path="/app/vault" element={<Protected><VaultPage/></Protected>}/><Route path="/app/gerador" element={<Protected><GeneratorPage/></Protected>}/><Route path="/app/senhas" element={<Protected><PasswordCheckerPage/></Protected>}/><Route path="/app/notificacoes" element={<Protected><NoticesPage/></Protected>}/><Route path="/app/sessoes" element={<Protected><SessionsPage/></Protected>}/><Route path="/app/configuracoes" element={<Protected><SettingsPage/></Protected>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes>}
